import{_ as r,C as o,o as n,c as l,a3 as a,E as s}from"./chunks/framework.CZBGEXos.js";const f=JSON.parse('{"title":"Начало работы","description":"","frontmatter":{},"headers":[],"relativePath":"ru/getting-started.md","filePath":"ru/getting-started.md"}'),i={name:"ru/getting-started.md"};function d(h,t,p,c,m,u){const e=o("Screenshot");return n(),l("div",null,[t[0]||(t[0]=a('<h1 id="начало-работы" tabindex="-1">Начало работы <a class="header-anchor" href="#начало-работы" aria-label="Permalink to &quot;Начало работы&quot;">​</a></h1><p>Sentaro — это десктопное приложение для мониторинга криптовалют под Windows. Оно читает общедоступные рыночные данные с Bybit, Binance, Gate.io, OKX и Hyperliquid (а также Kraken spot в <a href="/manual/ru/tools/ticks.html">Ticks</a>) и показывает их через набор инструментов, каждый из которых открывается в собственном окне с изменяемым размером.</p><h2 id="установка" tabindex="-1">Установка <a class="header-anchor" href="#установка" aria-label="Permalink to &quot;Установка&quot;">​</a></h2><ol><li>Скачайте установщик кнопкой <strong>Download</strong> на <a href="https://sentaro.trade/" target="_blank" rel="noreferrer">sentaro.trade</a>.</li><li>Запустите <code>.exe</code>.</li><li>Sentaro работает только на Windows. Сборок для macOS и Linux нет.</li></ol><h3 id="предупреждение-smartscreen" tabindex="-1">Предупреждение SmartScreen <a class="header-anchor" href="#предупреждение-smartscreen" aria-label="Permalink to &quot;Предупреждение SmartScreen&quot;">​</a></h3><p>При первой загрузке и запуске <strong>Windows Defender SmartScreen может предупредить, что приложение не распознано</strong>. Это ожидаемо и не является обнаружением вируса.</p><p>SmartScreen помечает любую новую программу, которая ещё не заработала репутацию у Microsoft, — это лишь значит, что файл скачало слишком мало людей, чтобы доверять ему автоматически. Через это проходит каждое новое независимое приложение, и предупреждение исчезает само, когда растёт число загрузок.</p><p>Чтобы его пройти:</p><ol><li>Нажмите <strong>Подробнее</strong> в окне SmartScreen.</li><li>Нажмите <strong>Выполнить в любом случае</strong>.</li><li>Это бывает только один раз — при следующих запусках предупреждения не будет.</li></ol><h2 id="первыи-запуск" tabindex="-1">Первый запуск <a class="header-anchor" href="#первыи-запуск" aria-label="Permalink to &quot;Первый запуск&quot;">​</a></h2><p>При запуске Sentaro сначала проверяет обновления, а затем просит войти.</p><h3 id="аккаунт" tabindex="-1">Аккаунт <a class="header-anchor" href="#аккаунт" aria-label="Permalink to &quot;Аккаунт&quot;">​</a></h3><p>Sentaro использует аккаунт с email и паролем. При регистрации на почту приходит 6-значный код подтверждения; введите его, чтобы подтвердить адрес, и после этого войдите. Во время регистрации также нужно принять Условия предоставления услуг.</p><p>Доступ сейчас бесплатный, пока Sentaro в бете. После входа вкладка <strong>Home</strong> показывает статус подписки <code>Beta Test</code>, а также ваш email и установленную версию приложения. Email по умолчанию скрыт — нажмите на иконку глаза рядом, чтобы его показать.</p><div class="tip custom-block"><p class="custom-block-title">Sentaro не имеет доступа к вашим биржевым аккаунтам</p><p>Все инструменты мониторинга читают только публичные рыночные данные. Sentaro не запрашивает API-ключи бирж, не подключается к вашему аккаунту и не может выставлять ордера ни на одной из бирж, которые он отслеживает.</p><p>Единственное исключение — экспериментальный <a href="/manual/ru/tools/terminal.html">Terminal</a>, отдельный инструмент, который вы включаете сами и подключаете к Hyperliquid, Binance или Bybit своими ключами. Без вашей сознательной настройки он ничего не делает.</p></div><h2 id="рабочее-пространство" tabindex="-1">Рабочее пространство <a class="header-anchor" href="#рабочее-пространство" aria-label="Permalink to &quot;Рабочее пространство&quot;">​</a></h2>',16)),s(e,{src:"workspace",alt:"Рабочее пространство Sentaro с несколькими открытыми окнами инструментов",caption:"Рабочее пространство Sentaro — несколько окон инструментов вокруг главного окна"}),t[1]||(t[1]=a('<p>Sentaro построен вокруг одного небольшого <strong>главного окна</strong> плюс по окну на каждый инструмент.</p><p>Слева в главном окне — вертикальная панель вкладок:</p><table tabindex="0"><thead><tr><th>Вкладка</th><th>Что содержит</th></tr></thead><tbody><tr><td>Home</td><td>Аккаунт, язык, акцентный цвет, настройки графиков и рисования</td></tr><tr><td>Knives</td><td>Настройки <a href="/manual/ru/tools/knives.html">Knives</a> + кнопка <strong>Open Window</strong></td></tr><tr><td>Alerts</td><td>Настройки <a href="/manual/ru/tools/alerts.html">Alerts</a> + кнопка <strong>Open Window</strong></td></tr><tr><td>Analyzer</td><td>Заметки <a href="/manual/ru/tools/analyzer.html">Analyzer</a> + кнопка <strong>Open Window</strong></td></tr><tr><td>Monitor</td><td>Настройки <a href="/manual/ru/tools/monitor.html">Monitor</a> + кнопка <strong>Open Window</strong></td></tr><tr><td>Terminal</td><td>Настройки <a href="/manual/ru/tools/terminal.html">Terminal</a> + кнопка <strong>Open Window</strong></td></tr><tr><td>Ticks</td><td>Настройки <a href="/manual/ru/tools/ticks.html">Ticks</a> + кнопка <strong>Open Window</strong></td></tr></tbody></table><p>Все инструменты работают одинаково: <strong>настройки живут в главном окне, а сам инструмент открывается отдельным окном.</strong> Нажмите <strong>Open Window</strong> во вкладке инструмента, чтобы его запустить. Пока это окно открыто, кнопка показывает <strong>Already Open</strong> и неактивна — у каждого инструмента может быть только одно окно.</p><p>Поскольку каждый инструмент — независимое окно, вы можете свободно менять их размер и расположение, собирая нужную раскладку, а главное окно убрать в сторону.</p><p>Изменения настроек применяются на лету — открытое окно инструмента подхватывает их без перезапуска. Настройки записываются на диск автоматически.</p><h3 id="заголовок-окна" tabindex="-1">Заголовок окна <a class="header-anchor" href="#заголовок-окна" aria-label="Permalink to &quot;Заголовок окна&quot;">​</a></h3><p>У окон инструментов собственный заголовок Sentaro вместо стандартного виндовского. Слева в нём <code>SENTARO</code> и название активного инструмента, справа — свернуть / развернуть / закрыть. Чтобы передвинуть окно, тяните за любое пустое место полосы.</p><h2 id="язык" tabindex="-1">Язык <a class="header-anchor" href="#язык" aria-label="Permalink to &quot;Язык&quot;">​</a></h2><p>Интерфейс Sentaro доступен на английском, украинском и русском. Переключить можно во вкладке <strong>Home</strong>, вверху справа у заголовка SENTARO. Эта настройка не связана с языком, на котором вы читаете этот справочник.</p><h2 id="сообщения-об-ошибках" tabindex="-1">Сообщения об ошибках <a class="header-anchor" href="#сообщения-об-ошибках" aria-label="Permalink to &quot;Сообщения об ошибках&quot;">​</a></h2><p>Когда что-то идёт не так — поток данных отключился, окно не открылось, сохранённые настройки не загрузились — в правом нижнем углу соответствующего окна появляется короткое сообщение. Оно исчезает само через несколько секунд, или нажмите <strong>×</strong>, чтобы закрыть его. Одно и то же сообщение показывается не чаще раза в 15 секунд, так что соединение, которое раз за разом переподключается, не засыплет экран.</p><p>Если ошибка возвращается снова и снова, напишите о ней в <a href="https://t.me/sentaro_trade" target="_blank" rel="noreferrer">Telegram-группу</a> с точным текстом.</p><h2 id="акцентныи-цвет" tabindex="-1">Акцентный цвет <a class="header-anchor" href="#акцентныи-цвет" aria-label="Permalink to &quot;Акцентный цвет&quot;">​</a></h2><p>Также во вкладке <strong>Home</strong> ряд из восьми цветовых образцов задаёт акцентный цвет всего приложения: Amber, Green, Blue, Purple, Red, Teal, Pink и White. Он действует во всех окнах инструментов.</p><p>Это отдельно от цветов свечей и метрик — о них см. <a href="/manual/ru/customize/chart-colors.html">Графики и рисование</a>.</p><h2 id="обновления" tabindex="-1">Обновления <a class="header-anchor" href="#обновления" aria-label="Permalink to &quot;Обновления&quot;">​</a></h2><p>Sentaro обновляется сам. При каждом запуске он проверяет наличие новой версии перед показом экрана входа; если она есть — скачивает, устанавливает и перезапускается автоматически. На экране загрузки при этом видно <code>Checking for updates...</code>, а затем <code>Updating to v&lt;версия&gt;...</code>.</p><p>Делать ничего не нужно. Установленная версия показана во вкладке <strong>Home</strong> как <strong>App Version</strong>.</p><h2 id="где-получить-помощь" tabindex="-1">Где получить помощь <a class="header-anchor" href="#где-получить-помощь" aria-label="Permalink to &quot;Где получить помощь&quot;">​</a></h2><p>Сообщения об ошибках и пожелания — в <a href="https://t.me/sentaro_trade" target="_blank" rel="noreferrer">группу Telegram</a>. Это самый быстрый способ получить прямой ответ.</p>',21))])}const _=r(i,[["render",d]]);export{f as __pageData,_ as default};
